export type TosspaymentsPaypalShippingAddress = {
    /**
     * 국가 코드 (ISO-3166 alpha-2, 예: "US")
     */
    country: string;
    /**
     * 도로명/건물/번지
     */
    line1?: string | undefined;
    /**
     * 상세 주소
     */
    line2?: string | undefined;
    /**
     * 주/도 (예: "CA")
     */
    area1?: string | undefined;
    /**
     * 도시명 (예: "San Jose")
     */
    area2: string;
    /**
     * 우편번호 (중국, 일본, 프랑스, 독일 등은 필수)
     */
    postalCode?: string | undefined;
};
